#!/usr/bin/env python3
"""Generate the Chinese report only from validated tables and chart facts."""
import argparse,csv,gzip,json
from pathlib import Path
import numpy as np
LOCAL=Path('/Users/hippo/Desktop/research_ws/umm/多轮次图像编辑/exp0_attention')
LABELS=['当前指令','历史指令合计','原图','历史生成图合计','正在生成的图','其他上下文','生成标记']
CATS=['current_instruction','history_instructions','original_image','history_images','target_image','context_other','generation_markers']
ROLES=[('current_instruction','text','当前指令'),('history_instruction','text','历史指令'),('original_image','vit','原图，ViT区域'),('original_image','vae','原图，VAE区域'),('history_image','vit','历史生成图，ViT区域'),('history_image','vae','历史生成图，VAE区域')]
def read(p):
    with gzip.open(p,'rt',encoding='utf-8',newline='') as f:return list(csv.DictReader(f))
def one(rows,**kw):
    x=[r for r in rows if all(r.get(k)==str(v) for k,v in kw.items())];assert len(x)==1,(kw,len(x));return x[0]
def main():
    p=argparse.ArgumentParser();p.add_argument('--input',type=Path,required=True);p.add_argument('--figures',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
    done=json.loads((a.input/'completion.json').read_text());assert done['status']=='passed' and done['input_turns']==1716
    f=json.loads((a.figures/'report_facts.json').read_text());s=json.loads((a.figures/'semantic_facts.json').read_text())
    comp=read(a.input/'tables/composition_summary.csv.gz');conc=read(a.input/'tables/concentration_summary.csv.gz');traj=read(a.input/'tables/trajectory_summary.csv.gz')
    within=read(a.input/'tables/within_type_summary.csv.gz');paired=read(a.input/'tables/paired_summary.csv.gz')
    def c(cat,t,metric='mass'):return float(one(comp,table='category_turn',category=cat,generation_turn=t,metric=metric)['mean'])
    def q(role,mod,t,metric,variant='main',grouping='object_role'):
        filters=dict(grouping=grouping,modality=mod,generation_turn=t,metric=metric,variant=variant)
        filters[grouping]=role;return float(one(conc,**filters)['mean'])
    def tr(typ,index,mod,t):return float(one(traj,object_type=typ,object_index=index,modality=mod,generation_turn=t,metric='mass')['mean'])
    def pair(typ,metric):return one(within,object_type=typ,modality='text' if typ=='text' else 'combined',older_index=1,newer_index=2,generation_turn=3,metric=metric)
    def pc(x,d=2):return f'{x*100:.{d}f}%'
    lines=[]
    def add(x=''):lines.append(x)
    def fig(n,name,caption):add(f'![图{n}：{caption}]({LOCAL}/attention分析图表/前三步/{name}.png)\n\n**图{n}｜{caption}。**\n')
    add('# EdiVal Attention 分析结果\n')
    add('本报告记录EdiVal全部572个会话、1716轮推理过程中的前三项描述统计：注意力总体分配、历史对象跨轮变化、指令和图片内部的集中程度。所有样本均参与分析，不按编辑成功或失败筛选。后续分析继续在本文中补充。\n')
    add('## 主要发现\n')
    add(f'1. **总体分配提供后续实验的基线。** 正在生成的图平均获得{pc(c("target_image","overall"))}的注意力，当前指令获得{pc(c("current_instruction","overall"))}。总份额与每个token的平均份额反映不同的分配特征，均不能直接代表对象对编辑结果的重要性。')
    add(f'2. **同类对象之间存在对较新对象的平均偏向。** 第3轮两条历史指令中，较旧的指令1占两者合计注意力的{pc(float(pair("text","older_share")["mean"]))}；两张历史生成图中，较旧的生成图1占{pc(float(pair("image","older_share")["mean"]))}。这一证据比单个对象的跨轮下降更明确，但尚不能证明模型遗忘了旧要求。')
    add(f'3. **内部注意力分配明显不均匀。** 当前指令中，关注最多的约10% token平均获得{pc(q("current_instruction","text","overall","top10pct_share"))}的组内注意力。图片内部按64个空间区域统计；其集中程度与文本token集中程度具有不同的观察分辨率。')
    add(f'4. **ViT存在明显的左上偏向，VAE没有普遍的左上最高现象。** 按实际关注量加权后，原图和历史图的ViT左上格分别占{ s["spatial"]["original_image_vit"]["pooled_corner_percent"]:.2f}%和{s["spatial"]["history_image_vit"]["pooled_corner_percent"]:.2f}%，高于均匀参考1.56%；VAE对应为{s["spatial"]["original_image_vae"]["pooled_corner_percent"]:.2f}%和{s["spatial"]["history_image_vae"]["pooled_corner_percent"]:.2f}%。图像标记单独统计，未算入空间格。\n')
    add('这些结果尚未与编辑成败建立关联，也未通过干预检验。它们用于提出下一步可验证的问题。\n')
    add('## 数据范围与阅读口径\n')
    add('### 观察对象\n')
    add('第1、2、3轮指三次连续编辑。一轮图像生成过程包含30个去噪步、36层和16个注意力头，共17,280组记录；注意力头可以理解为模型内部不同的注意力观察通道。每组记录已经把正在生成图像的1024个查询位置平均，描述这些位置合起来把注意力分给了哪些输入和当前图像token。\n')
    add('因此，本文不能判断输出图像的某个局部具体关注了哪个输入局部，也不能把本文的集中度解释为每个输出位置各自的集中度。例如，不同输出位置分别关注不同输入区域，汇总后的分布仍可能较均匀。\n')
    add('| 名称 | 含义 |\n| --- | --- |\n| 当前指令 | 本轮新提出的编辑要求 |\n| 历史指令 | 前几轮的编辑要求 |\n| 原图 | 会话开始时的输入图 |\n| 历史生成图 | 前几轮实际生成并放回上下文的图片 |\n| 正在生成的图 | 当前去噪中的图像表示，不是标准答案图 |\n| ViT / VAE | 同一张图片的两路编码，分别统计；整图份额为两路空间token的份额之和 |\n| 图像起止标记 | 包围图片表示的特殊token，归入其他上下文，不属于空间区域 |\n| 生成标记 | 当前图像生成所用的2个标记token |\n')
    add('文字最细统计到模型实际读取的token；英文单词可能拆成多个token。历史图片内部统计到8×8区域：ViT每格包含9个空间token，VAE每格包含16个空间token。本文的图片集中度是区域集中度。\n')
    add('### 平均方式与误差线\n')
    add('每轮先平均已保存的生成过程记录，再对会话等权平均。三轮整体先在每个会话内平均三轮，再平均会话。同一角色包含多张历史图时，先在同一会话、同一轮中对图片等权平均。长指令不会因token较多而自动增加样本权重。\n')
    add('尚不存在的历史类别，在总体份额中记为0；每token均值和内部集中度只分析对象已经存在的轮次。表格中的“—”表示尚未出现。95%误差区间通过2000次重采样计算；572个会话对应570个不同原图组，重采样以原图组为单位。17,280组记录和同一会话的三轮不作为独立样本。区间反映这批会话下的均值估计范围，不代表换种子或重复推理的波动，也不覆盖观测精度本身的误差。\n')
    add('## 注意力总体分配\n')
    add('### 各类对象的总份额\n')
    fig(1,'01_attention_allocation','全部对象的注意力分配及指令部分放大图')
    add('左图七类合计约100%；右图单独放大指令部分。\n')
    add('| 关注对象 | 第1轮 | 第2轮 | 第3轮 | 三轮整体 |\n| --- | ---: | ---: | ---: | ---: |')
    for cat,label in zip(CATS,LABELS):add('| '+label+' | '+' | '.join(pc(c(cat,t)) for t in [1,2,3,'overall'])+' |')
    add('\n所有份额来自同一套完整注意力分配，因此可以比较百分比。但文本、图像和标记承担不同功能，份额大小没有校准这些功能的价值。当前图像的份额也包含图像位置之间的联系。单凭它占比较高，不能判断模型有没有充分使用指令和历史。\n')
    add('### 每个token的平均份额\n')
    fig(2,'02_token_density','每个token的平均注意力与相对均匀分配的倍数')
    add('总份额除以该对象的实际token数，得到每token平均份额；再与“当前全部token均分注意力”比较，得到相对倍数。1倍表示等于均匀分配。图中使用对数刻度，相邻十倍刻度的间距相同。\n')
    add(f'当前指令的单个token平均获得{pc(c("current_instruction","overall","per_token_mass"),4)}，原图空间token平均获得{pc(c("original_image","overall","per_token_mass"),4)}。这拆分了token数量的影响，但仍不能认为两种token在语义功能上等价，也不能据此给文本和图片的重要性排序。\n')
    add('当前指令相对均匀分配的倍数依次为'+ '、'.join(f'{c("current_instruction",t,"enrichment"):.2f}倍' for t in [1,2,3])+'。由于上下文变长，均匀分配的基准也会变小；总份额下降与相对倍数上升可以同时出现。\n')
    add('| 图像类别 | 编码 | 第1轮 | 第2轮 | 第3轮 |\n| --- | --- | ---: | ---: | ---: |')
    for cat,label in [('original_image','原图'),('history_images','历史生成图合计')]:
        for mod in ['vit','vae']:
            vals=[float(one(comp,table='category_modality_turn',category=cat,modality=mod,generation_turn=t,metric='mass')['mean']) for t in [1,2,3]]
            add('| '+label+' | '+mod.upper()+' | '+' | '.join(pc(x) for x in vals)+' |')
    add('\n每张图包含576个ViT空间token和1024个VAE空间token，两路数量不同。整图每token均值按总量除以总token数计算，不能把两路每token均值简单平均。\n')
    add('总体分配主要提供可复现的基线和干预预算。提高整条指令或某类图像的份额只是候选实验；当前统计不能证明哪种调整会提升性能。\n')
    add('## 历史对象的跨轮分配\n')
    add('### 同一对象的轨迹\n')
    fig(3,'03_object_trajectories','同一条指令和同一张图片的跨轮轨迹')
    add('同一对象通过原指令内容和真实图片哈希确定身份。上排显示总份额，下排显示每token均值。对象出现前没有数据点。\n')
    add('| 对象 | 第1轮 | 第2轮 | 第3轮 |\n| --- | ---: | ---: | ---: |')
    for typ,idx,mod,label,start in [('text',1,'text','指令1',1),('text',2,'text','指令2',2),('text',3,'text','指令3',3),('image',0,'combined','原图',1),('image',1,'combined','第1轮生成图',2),('image',2,'combined','第2轮生成图',3)]:
        add('| '+label+' | '+' | '.join(pc(tr(typ,idx,mod,t)) if t>=start else '—' for t in [1,2,3])+' |')
    add('\n这里观察到的是直接分配的变化。新增历史对象会参与分配，旧要求也可能已体现在最新图像中，所以单个旧对象的份额下降不能单独证明遗忘或有害的信息丢失。\n')
    fig(4,'04_paired_changes','同一会话中的份额变化分布')
    add('横轴单位为百分点，左侧表示下降。每行使用572个成对会话。箱体为中间50%，须线为中间80%，菱形为平均变化；没有画出的尾部样本仍参与统计。\n')
    text_drop=one(paired,object_type='text',object_index=1,modality='text',turn_from=1,turn_to=3,metric='delta_mass')
    image_drop=one(paired,object_type='image',object_index=0,modality='combined',turn_from=1,turn_to=3,metric='delta_mass')
    add(f'从第1轮到第3轮，指令1的总份额平均下降{-float(text_drop["mean"])*100:.2f}个百分点，原图下降{-float(image_drop["mean"])*100:.2f}个百分点；两者在这批会话中出现下降的比例均为{pc(float(text_drop["negative_fraction"]))}。这说明直接份额下降很稳定，仍需下一项比较判断新旧对象之间的相对分配。\n')
    add('### 同一轮的同类对象比较\n')
    fig(5,'10_within_type_preference','同一轮中较旧对象与较新对象的分配')
    add('以“指令1 / 指令2”为例，把两条指令合计得到的注意力当作100%，看其中指令1拿到多少。50%表示两者总量相同。图中另给出按token数量调整后的比较；图片整图空间token数相同，两种比较重合。比例先在每组已汇总查询的记录中计算，再平均记录与会话。\n')
    add('| 比较对象 | 轮次 | 较旧对象在两者中的份额 | 每token调整后的份额 |\n| --- | ---: | ---: | ---: |')
    for typ in ['text','image']:
        for r in s[typ]:add(f'| {r["older"]} / {r["newer"]} | 第{r["turn"]}轮 | {r["older_share_percent"]:.2f}% | {r["older_density_share_percent"]:.2f}% |')
    text_recent=sum(r['older_share_percent']<50 for r in s['text']);image_recent=sum(r['older_share_percent']<50 for r in s['image'])
    add(f'\n上表四组指令比较中，有{text_recent}组较新对象获得更多总量；四组图片比较中，有{image_recent}组较新对象获得更多总量。这比只看跨轮下降更接近“同类信息中新旧对象的相对分配”。\n')
    same_text=next(r for r in s['text'] if r['turn']==3 and r['older']=='指令1' and r['newer']=='指令2')
    same_image=next(r for r in s['image'] if r['turn']==3 and r['older']=='生成图1' and r['newer']=='生成图2')
    add(f'其中，第3轮的指令1与指令2都属于历史指令，指令1在两者中占{same_text["older_share_percent"]:.2f}%，按token数量调整后占{same_text["older_density_share_percent"]:.2f}%；两张历史生成图之间，第1轮生成图占{same_image["older_share_percent"]:.2f}%。这两组比较避免把“历史对象与当前对象的角色差异”直接当作新旧效应；内容和任务需求仍未被控制。\n')
    text_ci=pair('text','older_share');image_ci=pair('image','older_share')
    add(f'上述两组总量比较的95%区间分别为{pc(float(text_ci["ci_low"]))}—{pc(float(text_ci["ci_high"]))}和{pc(float(image_ci["ci_low"]))}—{pc(float(image_ci["ci_high"]))}，都低于均分的50%。因此，这批数据中的平均偏向较明确，图片的新旧差距也比指令更大。这里比较的是注意力分配，尚未比较编辑质量。\n')
    add(f'这个方向对平均方式也较稳定：去掉两者合计份额不超过0.0001%的生成记录后，较旧历史指令和较旧历史图分别占{pc(float(pair("text","older_share_sensitivity")["mean"]))}和{pc(float(pair("image","older_share_sensitivity")["mean"]))}；在同一会话内按两者实际获得的关注量加权，再等权平均会话，分别为{pc(float(pair("text","pooled_older_share")["mean"]))}和{pc(float(pair("image","pooled_older_share")["mean"]))}。等权比例与关注量加权比例的数值不同，但都更偏向较新对象。\n')
    add('如果两者的份额一起按同一倍数缩小，二者内部比例保持不变。不过，新增上下文还会改变表示和不同查询的权重；原始查询已经平均，本文无法完全排除这些影响。指令长度、内容、当前任务需要和对象角色也没有被实验控制。因此，本结果描述相对偏向，不能给出“越旧必然越不重要”的因果结论。\n')
    add('## 对象内部的分布集中度\n')
    add('### 集中度指标\n')
    add('先把一条指令或一张图的一路编码自身获得的注意力当作100%，再看内部如何分配。\n')
    add('| 指标 | 直观含义 | 方向 |\n| --- | --- | --- |\n| 归一化熵 | 分布接近均匀还是偏向少数元素 | 越接近1越均匀 |\n| 前10%元素的份额 | 关注最多的一小部分合计拿到多少 | 越高越集中 |\n| 覆盖90%所需元素比例 | 从最受关注的元素开始累加，需要覆盖多少元素 | 越低越集中 |\n')
    add('前10%的元素数向上取整。64格图像实际取前7格，均匀分配的参考为10.94%；短指令取1个token就可能超过10%。指标先对每组已经平均查询的分布计算，再平均30步、36层和16个头，最后平均会话。不能先混成一张总平均图，再用总平均图的熵替代这些结果。\n')
    fig(6,'05_concentration_overview','内部集中程度及对应的均匀参考')
    add('圆点及细误差线是均值与95%区间，浅色粗线是会话间中间80%范围，灰色短线是与元素数匹配的均匀参考。\n')
    add('| 对象 | 归一化熵 | 前10%元素的份额 | 覆盖90%所需元素比例 |\n| --- | ---: | ---: | ---: |')
    for role,mod,label in ROLES:add(f'| {label} | {q(role,mod,"overall","normalized_entropy"):.3f} | {pc(q(role,mod,"overall","top10pct_share"))} | {pc(q(role,mod,"overall","n90_fraction"))} |')
    add('\n这些分布偏离均匀分配。但前一小部分得到较多 attention，并不意味着其余元素可以安全删掉：覆盖90%仍需保留表中所示比例的元素。图片按区域汇总，不能从区域集中度外推精确的图像token集中度；文本和图片也不宜在这一表中作语义重要性排序。\n')
    add('### 集中程度的跨轮变化\n')
    fig(7,'06_concentration_turns','集中程度的跨轮变化与极小份额敏感性')
    add('实线包含对象获得正份额的全部记录；虚线去掉该对象总份额不超过0.0001%的记录。第3轮的历史图角色先在每个会话内平均两张历史图。纵轴完整显示0%—100%。\n')
    add('原图VAE的前7格份额，前三轮依次为'+ '、'.join(pc(q('original_image','vae',t,'top10pct_share')) for t in [1,2,3])+'；对应归一化熵为'+ '、'.join(f'{q("original_image","vae",t,"normalized_entropy"):.3f}' for t in [1,2,3])+'。其内部集中程度从第1轮到第2轮上升，第2轮到第3轮没有继续明显上升，不能概括成每轮都越来越集中。\n')
    add('同一条指令1的前10%份额依次为'+ '、'.join(pc(q(1,'text',t,'top10pct_share',grouping='object_index')) for t in [1,2,3])+'，三轮均值的最大差距不到0.4个百分点。结合它的总份额下降，可以看到：旧指令得到的总量减少，内部集中程度却相对稳定。总量变化与内部形状变化需要分开讨论。\n')
    zero=f['low_mass_and_zero']['current_instruction_text']['zero_mass_fraction'];low=f['low_mass_and_zero']['current_instruction_text']['low_mass_fraction']
